'use strict';

// MODULES //

var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var abs = require( '@stdlib/math/base/special/abs' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );
var lnf = require( '@stdlib/math/base/special/lnf' );
var expm1 = require( '@stdlib/math/base/special/expm1' );
var NINF = require( '@stdlib/constants/float32/ninf' );


// MAIN //

/**
* Computes a one-parameter Box-Cox transformation for single-precision floating-point number.
*
* @param {number} x - input value
* @param {number} lambda - power parameter
* @returns {number} Box-Cox transformation
*
* @example
* var v = boxcoxf( 1.0, 2.5 );
* // returns 0.0
*
* @example
* var v = boxcoxf( 4.0, 2.5 );
* // returns ~12.4
*
* @example
* var v = boxcoxf( 10.0, 2.5 );
* // returns ~126.0911
*
* @example
* var v = boxcoxf( 2.0, 0.0 );
* // returns ~0.6931
*
* @example
* var v = boxcoxf( -1.0, 2.5 );
* // returns NaN
*
* @example
* var v = boxcoxf( 0.0, -1.0 );
* // returns -Infinity
*/
function boxcoxf( x, lambda ) {
	x = float64ToFloat32( x );
	lambda = float64ToFloat32( lambda );
	if ( isnan( x ) || isnan( lambda ) ) {
		return NaN;
	}
	if ( isPositiveZero( x ) && lambda < 0.0 ) {
		return NINF;
	}
	if ( abs( lambda ) < 1.0e-10 ) {
		return lnf( x );
	}
	return float64ToFloat32( expm1( lambda * lnf( x ) ) / lambda );
}


// EXPORTS //

module.exports = boxcoxf;
